import curses

def get_shape_input():
    """Get user input for shape type, size, and print it."""
    screen = curses.initscr()
    curses.noecho()
    curses.cbreak()
    try:
        shape_type = input("Enter the shape type (square, circle, triangle): ").lower()
        size = int(input("Enter the size: "))

        # Draw the shape based on the user input
        if shape_type == "square":
            draw_square(screen, size)
        elif shape_type == "circle":
            draw_circle(screen, size)
        elif shape_type == "triangle":
            draw_triangle(screen, size)
        else:
            print("Invalid shape type. Please try again.")

    finally:
        curses.endwin()

def draw_square(screen, size):
    """Draw a square of the given size on the terminal."""
    for i in range(size):
        for j in range(size):
            if i == 0 or i == size - 1 or j == 0 or j == size - 1:
                screen.addstr("*", curses.color_pair(1))
            else:
                screen.addstr(" ", curses.color_pair(0))
        screen.addstr("\n")

def draw_circle(screen, size):
    """Draw a circle of the given size on the terminal."""
    for i in range(size):
        for j in range(size):
            if (i - size // 2) ** 2 + (j - size // 2) ** 2 <= size // 2 ** 2:
                screen.addstr("*", curses.color_pair(1))
            else:
                screen.addstr(" ", curses.color_pair(0))
        screen.addstr("\n")

def draw_triangle(screen, size):
    """Draw a triangle of the given size on the terminal."""
    for i in range(size):
        for j in range(size):
            if i + j <= size - 1:
                screen.addstr("*", curses.color_pair(1))
            else:
                screen.addstr(" ", curses.color_pair(0))
        screen.addstr("\n")

if __name__ == "__main__":
    get_shape_input()
```

